import{_ as s,o as t,c as a,a3 as o}from"./chunks/framework.CagObDTx.js";const k=JSON.parse('{"title":"Session","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/session.md","filePath":"developers/commands/session.md"}'),i={name:"developers/commands/session.md"};function n(d,e,h,c,r,l){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ping</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> job</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>hello</code></td><td>Protocol and firmware versions, capability bits, <code>usbBudget</code> (what the USB-C port may draw: <code>DEFAULT</code>, <code>1.5A</code>, <code>3.0A</code>), serial number, limits (knobs, macros, racks, LFOs, snapshots, screen size)</td></tr><tr><td><code>ping</code></td><td>Empty round trip. The interface is alive</td></tr><tr><td><code>reset</code></td><td>Stops any open push or pull, clears queued events, subscribes again</td></tr><tr><td><code>job [HANDLE]</code></td><td>Status of a storage job (save, load, copy). No handle: the last job. <code>Busy</code> means ask again</td></tr><tr><td><code>abort</code></td><td>Stops an open <code>push</code>. Safe when nothing is being written</td></tr><tr><td><code>schema</code></td><td>Device types, parameters and enum tables (macro modes, menus, LFO parameters)</td></tr><tr><td><code>version</code></td><td>s32 CLI and protocol versions. In a REPL, also the firmware</td></tr><tr><td><code>help [COMMAND]</code></td><td>The overview, or the help of one command or group (same as <code>COMMAND --help</code>)</td></tr><tr><td><code>completion bash|zsh</code></td><td>A shell completion script on stdout. No S32 needed</td></tr><tr><td><code>commands</code></td><td>Every command with its one-line summary. <code>commands --json</code> describes every command, key and example for programs, and marks service commands (<code>&quot;service&quot;: true</code>), such as <code>reset</code>; scripts and AI agents should leave them to a person. <code>--dev</code> adds commands and values for hardware that is not released yet. No S32 needed</td></tr></tbody></table><p><code>s32 --version</code> needs no S32.</p><h2 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # the overview</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # every macro command with an example</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # arguments, keys with their allowed values, examples</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # the same</span></span></code></pre></div><p>Help comes from the same declarations that check your input, so a key listed in help is a key the command accepts. None of it needs an S32. <code>--help</code> works anywhere on a command line, in a script line and in a REPL line.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>OK</td></tr><tr><td><code>1</code></td><td>Local file or OS error: a script, input or output file on this computer</td></tr><tr><td><code>2</code></td><td>Usage: unknown command or key, a missing or malformed argument</td></tr><tr><td><code>3</code></td><td>Link: no reply (<code>timed out</code>), a malformed reply, USB lost, or the s32 CLI and your S32&#39;s firmware speak different editor protocols</td></tr><tr><td><code>4</code></td><td>Refused: the S32 answered with a status (<code>NotFound</code>, <code>Busy</code>, ...), the target does not exist, or the S32 was edited (panel or web editor) while s32 read a list</td></tr><tr><td><code>5</code></td><td>Not confirmed: a command that asks first ran without <code>--yes</code> and no terminal, or you answered no</td></tr></tbody></table><p>A script exits with the code of the line that failed. Every error is <code>error: &lt;what&gt;</code> followed by one line that says what to do next: the usage line, a close command or key (<code>did you mean: s32 macro set</code>), or a hint such as <code>next: check the USB cable and close the web editor, then run &#39;s32 hello&#39;</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># error: unknown command &#39;macor&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># did you mean: s32 macro</span></span></code></pre></div><p>When the s32 CLI and your S32&#39;s firmware speak different editor protocols, the error names the older side and says how to update it. The numbers are the editor protocol of each side:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: the s32 command-line tool is older than your S32&#39;s firmware (the tool speaks editor protocol 4, your S32 speaks 5)</span></span>
<span class="line"><span>next: update the s32 command-line tool: run the one-line install again (https://s32-manual.shik.tech/developers/getting-started)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>error: your S32&#39;s firmware is older than the s32 command-line tool (your S32 speaks editor protocol 3, the tool speaks 4)</span></span>
<span class="line"><span>next: update your S32&#39;s firmware: SETTINGS &gt; FIRMWARE &gt; FIRMWARE UPDATE (https://shik.tech/support/manuals-firmware/)</span></span></code></pre></div><h2 id="quiet" tabindex="-1">Quiet <a class="header-anchor" href="#quiet" aria-label="Permalink to &quot;Quiet&quot;">​</a></h2><p><code>-q</code> (or <code>--quiet</code>) prints results only: no USB warning, no script echo (<code>--- [N] line</code>), no <code>script passed</code>, no retry notices, no REPL banner. Errors and their next-step line always print. The state a <a href="#a-set-prints-the-state-it-left">set prints back</a> is a result, so <code>-q</code> keeps it.</p><h2 id="json-output" tabindex="-1">JSON output <a class="header-anchor" href="#json-output" aria-label="Permalink to &quot;JSON output&quot;">​</a></h2><p><code>--json</code> prints the result of a command as one JSON object on one line, for your own tools and scripts. It works on every read command and on every set (see below):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bpm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120.00</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bpmX100&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;clockMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;internal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;externalClock&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;off&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;transport&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stopped&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;outputFull&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;off&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><strong>One object, one line.</strong> stdout carries only that object: no USB warning, no echo, no banner. <code>--json</code> implies <code>-q</code>.</li><li><strong>Keys are the names you type.</strong> A field that a set command takes as <code>key=value</code> has that key as its name (<code>channel</code>, <code>cvOut</code>, <code>targetLfo</code>, <code>cc</code>). When the text prints another spelling the key is the accepted one: <code>extmap list</code> prints <code>num=</code> and <code>dev=</code>, the JSON says <code>cc</code> and <code>device</code>. A field no command takes keeps the word the text prints (<code>jobState</code>, <code>backStack</code>).</li><li><strong>Words, numbers, null.</strong> An enum or yes/no is the exact word you can pass back (<code>&quot;on&quot;</code>, <code>&quot;global&quot;</code>, <code>&quot;yes&quot;</code>). A number is a JSON number with the text&#39;s precision (<code>0.500</code>, <code>120.00</code>). Positions (<code>index</code>, <code>slot</code>, <code>pot</code>, <code>macro</code>, <code>lfo</code>, …) are the panel&#39;s numbers, from 1. A name is a string with no padding. An empty slot, a rack or device that is not set, and a field that does not apply to the target are <code>null</code>. Masks stay hex strings (<code>&quot;0x9000&quot;</code>). A value the text prints as <code>none</code> (<code>sub</code>, <code>lfo</code>, <code>cvOut</code>, <code>active</code>, <code>pinA</code>, <code>pinB</code>, the <code>view state</code> context) is <code>null</code>.</li><li><strong>Fields the text prints only sometimes</strong> are always there, <code>null</code> when the text leaves them out: <code>job --json</code> has <code>volume</code> (<code>0</code> internal, <code>1</code> card), set only for a save-as or duplicate job.</li><li><strong>Lists</strong> are a plural array plus their counters (<code>{&quot;count&quot;:1,&quot;max&quot;:8,&quot;racks&quot;:[...]}</code>); every row carries its <code>index</code> or <code>slot</code>.</li><li><strong>Escaping.</strong> Strings follow RFC 8259: <code>&quot;</code> and <code>\\</code> are escaped, control bytes become <code>\\u00XX</code>, valid UTF-8 passes through, and a byte that is not valid UTF-8 becomes <code>\\u00XX</code> (its Latin-1 reading), so the output is always valid JSON.</li><li><strong><code>schema --json</code></strong> is <code>schema --emit-schema-json</code>, unchanged. <code>layout</code> keeps <code>--emit-layout-json</code>.</li></ul><p>A command with no JSON form (<code>watch</code>, <code>pull</code>, <code>screen png</code>, <code>pause</code>, <code>help</code>, <code>completion</code>, <code>layout</code>, and every write that does not print a state back, such as <code>device add</code> or <code>project delete</code>) refuses <code>--json</code> with exit code 2 and sends nothing:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: --json is not available for &#39;s32 watch&#39;</span></span></code></pre></div><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><p>With <code>--json</code> a failure prints exactly one JSON object on stderr and leaves stdout empty. The exit code is the same as without <code>--json</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chanel=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;class&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;usage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;unknown key &#39;chanel&#39;; usage: macro set …&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;next&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;did you mean: channel=&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;suggestions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;channel=&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;applied&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>The <a href="#exit-codes">exit code</a></td></tr><tr><td><code>class</code></td><td>One word per code: <code>local</code> (1), <code>usage</code> (2), <code>link</code> (3), <code>refused</code> (4), <code>declined</code> (5)</td></tr><tr><td><code>message</code></td><td>The text after <code>error: </code>, unchanged</td></tr><tr><td><code>next</code></td><td>The next-step line, or <code>null</code> when there is none</td></tr><tr><td><code>suggestions</code></td><td>The &quot;did you mean&quot; candidates, in the order the text prints them, or <code>[]</code></td></tr><tr><td><code>status</code></td><td>The S32 status word (<code>&quot;NotFound&quot;</code>) for class <code>refused</code>; <code>&quot;VersionMismatch&quot;</code> when the tool and the S32 speak different editor protocols (class <code>link</code>); otherwise <code>null</code>. It is also <code>null</code> for the refused error &quot;the S32 changed while s32 read the list&quot;, where the S32 sent no status</td></tr><tr><td><code>applied</code></td><td><code>true</code> when the S32 acknowledged a write of this command before it failed, so a program can tell &quot;nothing changed&quot; from &quot;changed, not confirmed&quot;. For class <code>link</code> a write whose reply was lost may still have landed on the S32. It is <code>true</code> for &quot;added assignment N, but the S32 changed while s32 read …&quot;: the write was saved before the read-back saw the change</td></tr></tbody></table><p>Errors that come before the command is known are JSON too: an unknown command, an unknown word under a group (<code>macro sett 5 2</code>, with the close command in <code>suggestions</code>). In a script or REPL line the object also has <code>line</code> (the line number) and <code>text</code> (the line).</p><p><code>--json</code> does not prompt, not even on a terminal. A command that asks first and has a JSON form (<code>globals set</code>) exits with code 5 and the <code>declined</code> error unless you pass <code>--yes</code>; nothing is sent. The other commands that ask (<code>rack clear</code>, <code>project delete</code>, ...) have no JSON form, so <code>--json</code> on them is the usage error above, with or without <code>--yes</code>.</p><h3 id="a-set-prints-the-state-it-left" tabindex="-1">A set prints the state it left <a class="header-anchor" href="#a-set-prints-the-state-it-left" aria-label="Permalink to &quot;A set prints the state it left&quot;">​</a></h3><p>After a set succeeds, the CLI reads the state back from the S32 and prints it: your own confirmation line first (unchanged), then the lines the matching <code>get</code> prints. The state comes from a real request, so it shows what the S32 stored, which can differ from what you sent (a value it rounded or limited).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ s32 --loopback macro set 5 2 channel=3</span></span>
<span class="line"><span>macro 5/2 updated</span></span>
<span class="line"><span>pot 5 macro 2: mode=disabled msb=0 lsb=0 channel=3 min=0.000 max=127.000 ...</span></span></code></pre></div><ul><li><strong>Lists</strong> print only the row you changed, with no list header: <code>rack set 1 bypass=on</code> prints <code>rack 1 bypass=on</code> and then <code> [1] id=100 bypass=on in=yes devices=1 Rack 1</code>.</li><li><strong><code>--json</code></strong> prints only the read-back object (for a list, the changed row&#39;s object); the confirmation line is not printed.</li><li><strong><code>device param set</code></strong> reads back one parameter per <code>PARAM=VALUE</code>, in the order given: one line each in text, one object with a <code>params</code> array in JSON.</li><li><strong>Five sets already printed their state.</strong> <code>snapshot parent set</code>, <code>snapshot flags set</code>, <code>snapshot bank set</code>, <code>device host-device ... host=</code> and <code>extmap set</code> print the state line themselves, so the same line shows twice: the confirmation, then the read-back.</li><li>A read-back that fails never repeats the set. Text: the confirmation line, then the read&#39;s <code>error:</code> line. <code>--json</code>: one error with <code>&quot;applied&quot;:true</code>.</li></ul><p>The set commands with a read-back are <code>macro set</code>, <code>potname set</code>, <code>lfo cfg set</code>, <code>lfo assign add|set</code>, <code>rack set|rename</code>, <code>device param set</code>, <code>device host-device</code>, <code>stepseq set</code>, <code>extmap add|set</code>, <code>meta set</code>, <code>globals set</code> and <code>snapshot sequence|arrange|flags|parent|bank|morph set</code>.</p><h3 id="scripts-and-the-repl" tabindex="-1">Scripts and the REPL <a class="header-anchor" href="#scripts-and-the-repl" aria-label="Permalink to &quot;Scripts and the REPL&quot;">​</a></h3><p><code>s32 --json --script FILE</code> and <code>s32 --json repl</code> print one JSON object per command line that succeeds, and nothing else: no <code>--- [N]</code> echo, no <code>script passed:</code>, no REPL banner, no <code>s32&gt; </code> prompt, no retry notices (a retried line reports only its final result). A failing script line prints one JSON error with <code>line</code> and <code>text</code>, and the script stops with that line&#39;s exit code. A failing REPL line prints the same error and the REPL goes on. Put <code>--json</code> on a single line of a normal script to get JSON for that line only; the echo and the <code>script passed:</code> line stay.</p><h3 id="stability" tabindex="-1">Stability <a class="header-anchor" href="#stability" aria-label="Permalink to &quot;Stability&quot;">​</a></h3><p>Within a CLI major version (<code>1.x.y</code>), a JSON key or error field is never renamed or removed and its type never changes. New keys can be added: ignore keys you do not know. Every read command has a checked-in JSON Schema in <code>tools/s32-cli/json/</code>.</p><h2 id="preview-before-a-change" tabindex="-1">Preview before a change <a class="header-anchor" href="#preview-before-a-change" aria-label="Permalink to &quot;Preview before a change&quot;">​</a></h2><p><code>--dry-run</code> works on every command that changes the S32, and on <code>pull</code>. It checks the command exactly as the real run does, reads what it needs from the S32, prints the change it would make and exits 0. <strong>It sends no write</strong>, and it needs no <code>--yes</code> and does not prompt, even for <code>project delete</code>, <code>project load</code>, <code>push --activate</code>, <code>rack clear</code>, <code>rack duplicate</code>, <code>snapshot delete</code> and <code>globals set</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> msb=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">74</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dry-run: s32 macro set 5 2 channel=3 msb=74 (nothing sent)</span></span>
<span class="line"><span>  channel: global -&gt; 3</span></span>
<span class="line"><span>  msb: 0 -&gt; 74</span></span></code></pre></div><ul><li>A key that keeps its value prints <code>msb: 0 (unchanged)</code>. A key that creates a row (<code>extmap add</code>, <code>lfo assign add</code>) prints <code>ch: (new) -&gt; 1</code>.</li><li>A command that changes no named key prints one <code> would …</code> sentence: <code>would permanently remove the stored project vol=0 uid=3 name=Project 3</code>, <code>would remove every device in rack 1 (id 100, 1 devices)</code>.</li><li>Wrong arguments, an unknown key or a project that does not exist fail with the same exit code and message as the real command. <code>--dry-run</code> on any other command that does not change the S32 (<code>macro get</code>, <code>commands</code>) is a usage error.</li><li>With <code>--json</code> it prints one object: <code>{&quot;dryRun&quot;:true,&quot;command&quot;:&quot;macro set&quot;,&quot;target&quot;:{&quot;pot&quot;:5,&quot;macro&quot;:2},&quot;destructive&quot;:false,&quot;changes&quot;:[{&quot;key&quot;:&quot;channel&quot;,&quot;from&quot;:&quot;global&quot;,&quot;to&quot;:&quot;3&quot;}],&quot;would&quot;:null}</code>. <code>from</code> and <code>to</code> are the words the CLI prints and accepts; <code>from</code> is <code>null</code> for a new row. <code>target</code> has one member per target argument you typed (a number when you typed a plain integer, otherwise a string).</li><li><code>--dry-run</code> checks only what the CLI can check: the S32 can still refuse the real write. Its reads count against the S32&#39;s rate limit like any read.</li></ul><h2 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> completion bash)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # bash: add this line to ~/.bashrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> completion zsh)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # zsh: add this line to ~/.zshrc</span></span></code></pre></div><p>Press Tab to complete commands, verbs, <code>key=</code> names and the words after <code>key=</code> (<code>macro set 5 2 mode=</code> lists the macro modes).</p><h2 id="schema-json" tabindex="-1">Schema JSON <a class="header-anchor" href="#schema-json" aria-label="Permalink to &quot;Schema JSON&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-schema-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema.json</span></span></code></pre></div><p>Over <code>--loopback</code> the schema lists every real device type with its real parameters (<a href="./../simulator">simulator</a>).</p>`,49)])])}const u=s(i,[["render",n]]);export{k as __pageData,u as default};
